style.css:
@-moz-document domain("roblox.com") {
:root {
        --wm-bg: #05010d;        /* Deepest Void */
        --wm-border: #7a3ee6;    /* World Machine Purple */
        --wm-panel: rgba(20, 5, 40, 0.95);
        --wm-text: #cbb1ff;
        --wm-gold: #ffcc33;
        --wm-grid: rgba(122, 62, 230, 0.2);
    }

    /* --- THE GRID & BINARY BACKDROP --- */
    html, body {
        background-color: var(--wm-bg) !important;
        background-image: 
            linear-gradient(var(--wm-grid) 1.5px, transparent 1.5px),
            linear-gradient(90deg, var(--wm-grid) 1.5px, transparent 1.5px) !important;
        background-size: 50px 50px !important;
        background-attachment: fixed !important;
        animation: grid-scroll 30s linear infinite !important;
    }

    @keyframes grid-scroll {
        from { background-position: 0 0; }
        to { background-position: 500px 500px; }
    }

    /* Binary code streams on the very back layer */
    body::before {
        content: "10101101001\a 01101010110\a 10110100111\a 00101011010\a 11010101010\a 01011011101";
        position: fixed;
        top: 0; left: 5px;
        font-family: monospace;
        color: var(--wm-border);
        opacity: 0.1;
        font-size: 12px;
        white-space: pre;
        z-index: -1;
        animation: binary-fall 20s linear infinite;
    }

    @keyframes binary-fall {
        from { top: -100%; }
        to { top: 100%; }
    }

    /* --- TRANSPARENCY FIX (Removing the Gray) --- */
    .content, .container-main, .container-fluid, .bg-container, #container-main,
    .section, .rbx-left-col, .main-layout, .container-footer, .footer {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* --- TOP BAR (HEADER) FIX --- */
    #header, .rbx-header {
        background-color: #000 !important;
        border-bottom: 3px solid var(--wm-border) !important;
        box-shadow: 0 0 15px rgba(122, 62, 230, 0.5) !important;
    }

    /* --- SEARCH BAR THEME --- */
    .navbar-search, .navbar-search .input-group, .rbx-header .navbar-search .input-field {
        background-color: #000 !important;
        border: 2px solid var(--wm-border) !important;
        border-radius: 0px !important;
        color: var(--wm-text) !important;
        box-shadow: none !important;
    }

    /* --- PANELS & SERVER LISTS (Game Instances) --- */
    /* This fixes the gray box in your server screenshot */
    .section-content, 
    .rbx-instance-card, 
    .item-card-container, 
    .game-card-container,
    .profile-header,
    .stack-row,
    .rbx-private-server-banner,
    .card-item {
        background-color: var(--wm-panel) !important;
        border: 2px solid #000 !important;
        outline: 2px solid var(--wm-border) !important;
        border-radius: 0px !important;
        box-shadow: 8px 8px 0px rgba(0,0,0,0.8) !important;
        overflow: hidden !important;
        margin-bottom: 15px !important;
    }

    /* --- TEXT GLOW (Universal) --- */
    * {
        text-shadow: 0 0 5px rgba(122, 62, 230, 0.6) !important;
    }

    h1, h2, h3, .text-name, .text-title, .rbx-lead, .profile-header-name, span, a, div {
        color: var(--wm-text) !important;
        font-family: "Courier New", monospace !important;
        text-transform: lowercase;
    }

    /* --- SIDEBAR & FOOTER --- */
    .left-col-list, #navigation, .nav-content, #footer {
        background-color: var(--wm-panel) !important;
        border-right: 3px solid var(--wm-border) !important;
        border-top: 3px solid var(--wm-border) !important;
    }

    /* --- BUTTONS & JOIN BUTTONS --- */
    .btn-common-play-main, .btn-full-width, .rbx-instance-join, .btn-primary-md, .btn-secondary-xs {
        background-color: #000 !important;
        border: 2px solid var(--wm-gold) !important;
        color: var(--wm-gold) !important;
        box-shadow: 0 0 10px var(--wm-gold) !important;
        border-radius: 0px !important;
        text-shadow: 0 0 5px var(--wm-gold) !important;
    }

    /* --- SCAN-LINE --- */
    body::after {
        content: "";
        position: fixed;
        top: -10%; left: 0;
        width: 100%; height: 2px;
        background: var(--wm-border);
        box-shadow: 0 0 15px 1px var(--wm-border);
        z-index: 9999;
        opacity: 0.1;
        pointer-events: none;
        animation: scan-move 10s linear infinite;
    }

    @keyframes scan-move {
        0% { top: -10%; }
        100% { top: 110%; }
    }

    /* Avatars to square */
    .avatar, .avatar-card-fullbody, .avatar-headshot-md, .profile-avatar-left {
        border-radius: 0px !important;
        border: 2px solid var(--wm-border) !important;
    }
}
